PREPARE d_comment_stmt FROM @d_comment_sql;
EXECUTE d_comment_stmt;
DEALLOCATE PREPARE d_comment_stmt;
SET @d_comment_sql = IF(EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='journal' AND COLUMN_NAME='created_at' AND COLUMN_COMMENT='创建时间' AND COLUMN_TYPE <=> 'datetime' AND IS_NULLABLE <=> 'NO' AND COLUMN_DEFAULT <=> 'CURRENT_TIMESTAMP' AND EXTRA <=> 'DEFAULT_GENERATED' AND COLLATION_NAME <=> NULL AND GENERATION_EXPRESSION <=> ''), 'ALTER TABLE `journal` MODIFY COLUMN `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT ''''', 'DO 0');
PREPARE d_comment_stmt FROM @d_comment_sql;
EXECUTE d_comment_stmt;
DEALLOCATE PREPARE d_comment_stmt;
